{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Halofantrine, the closest structural analogue (dibutylamino alcohol antimalarial with a chlorinated aromatic core), has an average absolute oral bioavailability of approximately 30% in humans in the fasted state, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Zotepine, a tricyclic chlorinated antipsychotic with some similarity, has an absolute bioavailability of only 7–13%, below the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C32"],
      "claim": "Ixazomib, a moderately similar molecule, has an estimated absolute oral bioavailability of 60% in patients, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Almokalant, a moderately similar molecule, has an absolute oral bioavailability of approximately 50% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue halofantrine has a measured absolute oral bioavailability of ~30% in humans, above the 20% threshold, and the majority of other retrieved analogues with moderate-to-low similarity also show F ≥ 20%. The only low-F analogue (zotepine, 7–13%) is structurally distant and outweighed. Therefore, high oral bioavailability (F ≥ 20%) is predicted.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Halofantrine evidence includes qualitative 'low' reports that conflict with the quantitative 30% estimate.",
    "Most analogues have low Morgan similarity (<0.25), limiting transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

